def check_solution(n):
    value = 2**n - 3
    if value <= 0:
        return False

    k = 0
    power_of_5 = 1
    while power_of_5 < value:
        power_of_5 *= 5
        k += 1

    if power_of_5 == value:
        print(f"n={n} is a solution. 2^{n} - 3 = 5^{k} where k={k}")
        return True
    else:
        print(f"n={n} is not a solution. 2^{n} - 3 = {value}")
        return False

# Check n from 3 up to 15
for n in range(3, 16):
    check_solution(n)

def is_power_of_5(N):
    """Checks if N is a power of 5 (i.e., N = 5^k for k >= 1)."""
    if N <= 0:
        return False
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

print("Testing n from 3 to 20:")
solutions = []
for n in range(3, 21):
    val = (2**n) - 3
    if is_power_of_5(val):
        solutions.append(n)
        print(f"n={n}: 2^{n} - 3 = {val} (Power of 5)")

print("\nSolutions found up to n=20:", solutions)
